async function setup() {
  _regW(0xE0028008, 0x01);  // P0.0 = OUTPUT
  _regW(0xE0004004, 0x02);  // Timer0 reset
  _regW(0xE0004004, 0x01);  // Timer0 enable
  _regW(0xE0004014, 0x01);  // MCR: reset on MR0 match
  _regW(0xE0004018, 7500000); // MR0 = 7500000 (500ms at 15MHz)
}

async function loop() {
  var ir = _regR(0xE0004000);
  if (ir & 1) {
    _regW(0xE0004000, 1);
    _regW(0xE0028004, 0x01); // Toggle P0.0
  }
  await delay_ms(1);
}
